  // Lazy initialize ~standard to avoid creating objects for every schema
  util.defineLazy(inst, "~standard", () => ({
    validate: (value: unknown) => {
      try {
        const r = safeParse(inst, value);
        return r.success ? { value: r.data } : { issues: r.error?.issues };
