export function isPlainObject(o: any): o is Record<PropertyKey, unknown> {
  if (isObject(o) === false) return false;

  // modified constructor
  const ctor = o.constructor;
  if (ctor === undefined) return true;

  if (typeof ctor !== "function") return true;

  // modified prototype
  const prot = ctor.prototype;
  if (isObject(prot) === false) return false;

  // ctor doesn't have static `isPrototypeOf`
  if (Object.prototype.hasOwnProperty.call(prot, "isPrototypeOf") === false) {
    return false;
  }

  return true;
}

function enumerableKeys(value: object): PropertyKey[] {
  return Reflect.ownKeys(value).filter((key) => Object.prototype.propertyIsEnumerable.call(value, key));
}

function hasPerfectMatching(edges: boolean[][]): boolean {
  const matched = new Array(edges.length).fill(-1);
  const visit = (left: number, seen: boolean[]): boolean => {
    for (let right = 0; right < edges[left]!.length; right++) {
      if (!edges[left]![right] || seen[right]) continue;
      seen[right] = true;
      if (matched[right] === -1 || visit(matched[right]!, seen)) {
        matched[right] = left;
        return true;
      }
    }
    return false;
  };
  return edges.every((_, left) => visit(left, new Array(edges.length).fill(false)));
}

export function shallowEqual(a: unknown, b: unknown): boolean {
  if (Object.is(a, b)) return true;
  if (Array.isArray(a) && Array.isArray(b)) {
    return a.length === b.length && a.every((value, index) => Object.is(value, b[index]));
  }
  if (a instanceof Map && b instanceof Map) {
    if (a.size !== b.size) return false;
    const right = [...b];
    return hasPerfectMatching(
      [...a].map(([key, value]) => right.map(([otherKey, otherValue]) => Object.is(key, otherKey) && Object.is(value, otherValue)))
    );
  }
  if (a instanceof Set && b instanceof Set) {
    if (a.size !== b.size) return false;
    const right = [...b];
    return hasPerfectMatching([...a].map((value) => right.map((other) => Object.is(value, other))));
  }
  if (isPlainObject(a) && isPlainObject(b)) {
    const aKeys = enumerableKeys(a);
    const bKeys = enumerableKeys(b);
    return (
      aKeys.length === bKeys.length &&
      aKeys.every((key) => bKeys.includes(key) && Object.is(a[key], b[key]))
    );
  }
  return false;
}

